<?php require __DIR__.'/_auth.php'; ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Início · Larissa Beauty</title><link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@500;600&family=Montserrat:wght@400;500;600&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/admin.css"></head><body><div class="app"><nav class="menu"><a class="marca" href="dashboard.php">Larissa Beauty</a><a class="link on" href="dashboard.php">Início</a><a class="link " href="agenda.php">Agenda</a><a class="link " href="servicos.php">Serviços</a><a class="link " href="horarios.php">Horários</a><a class="link sair" href="#" id="sair">Sair</a></nav><main class="conteudo"><div class="cabeca"><div><h1 id="saudacao">Olá!</h1><p id="data-hoje"></p></div><a class="btn" href="agenda.php">Ver agenda completa</a></div><section class="numeros"><div class="numero destaque"><b id="n-hoje">—</b><span>atendimentos hoje</span></div><div class="numero"><b id="n-pend">—</b><span>aguardando confirmação</span></div><div class="numero"><b id="n-sem">—</b><span>próximos 7 dias</span></div></section><h2>Hoje</h2><div class="lista" id="lista-hoje"><div class="vazio">Carregando dados...</div></div></main></div><script>
async function api(url,method='GET',data=null){const opt={method,credentials:'same-origin',cache:'no-store',headers:{}};if(data!==null){const m=await fetch('../backend/api/me.php',{credentials:'same-origin',cache:'no-store'}).then(r=>r.json());if(!m.csrf)throw Error('Sessão expirada. Entre novamente.');opt.headers['Content-Type']='application/json';opt.headers['X-CSRF-Token']=m.csrf;opt.body=JSON.stringify(data);}const r=await fetch('../backend/api/'+url,opt);const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.erro||'Erro na operação ('+r.status+').');return d;}
document.getElementById('sair')?.addEventListener('click',async e=>{e.preventDefault();try{await api('logout.php','POST',{});}finally{location.href='login.php';}});
const br=d=>new Date(d+'T12:00:00').toLocaleDateString('pt-BR'), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
</script><script>
document.getElementById('data-hoje').textContent=new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'});
async function carregar(){try{const d=await api('admin_resumo.php');document.getElementById('saudacao').textContent='Olá, '+esc(d.nome)+' :)';document.getElementById('n-hoje').textContent=d.hoje;document.getElementById('n-pend').textContent=d.pendentes;document.getElementById('n-sem').textContent=d.proximos;const l=document.getElementById('lista-hoje');l.innerHTML=d.lista.length?d.lista.map(a=>`<div class="item"><span class="hora">${a.hora}</span><div><span class="nome">${esc(a.cliente_nome)}</span><span class="tag ${a.status}">${a.status}</span><small>${esc(a.servico)}</small></div><div class="acoes">${a.status==='pendente'?`<button class="btn" data-status="confirmado" data-id="${a.id}">Confirmar</button>`:''}${['pendente','confirmado'].includes(a.status)?`<button class="btn perigo" data-status="cancelado" data-id="${a.id}">Cancelar</button>`:''}</div></div>`).join(''):'<div class="vazio">Nenhum atendimento para hoje.</div>';}catch(e){document.getElementById('lista-hoje').innerHTML='<div class="vazio">'+esc(e.message)+'</div>';}}
document.getElementById('lista-hoje').addEventListener('click',async e=>{const b=e.target.closest('[data-status]');if(!b)return;if(!confirm('Confirma esta alteração?'))return;try{await api('atualizar_status.php','POST',{agendamento_id:Number(b.dataset.id),status:b.dataset.status});carregar();}catch(x){alert(x.message);}});carregar();
</script></body></html>